PERSON_OWN = object()       # the grants of person_agent_view and conversation_refusal: the person's own list


def person_scope(pid, agent):
    """The list of one person's conversations with one agent, {resource id: level}, or None for All. A row that cannot
    be read is an empty list, never All. read_row only: safe inside a caller's transaction."""
    row = read_row("SELECT grants FROM person_scopes WHERE person=? AND agent=?", (pid, agent))
    if row is None:
        return None
    try:
        grants = json.loads(row["grants"])
    except (TypeError, ValueError):
        return {}
    return {str(k): v for k, v in grants.items() if isinstance(v, str)} if isinstance(grants, dict) else {}


def task_scope(t):
    """{"person", "grants"} of a task row that a narrowed person's words drive, or None. That is a task born of a
    narrowed pair (tasks.scope_person), and also a task of a conversation whose pair is narrowed now, born before its
    list: the stricter of the two always holds. Only the owner's own write takes a task's person away: a list back to
    All gives the pair's open tasks the agent's tools again (person_scope_rows). Otherwise a task whose list is gone
    reads an empty list. read_row only."""
    if t is None:
        return None
    keys = t.keys()
    pid = t["scope_person"] if "scope_person" in keys else None
    if pid is None and "source_conversation" in keys and t["source_conversation"] is not None:
        c = read_row("SELECT person FROM conversations WHERE id=?", (t["source_conversation"],))
        pid = c["person"] if c and person_scope(c["person"], t["owner"]) is not None else None
    return None if pid is None else {"person": pid, "grants": person_scope(pid, t["owner"]) or {}}


def session_scope(agent, context=None):
    """The list that holds for the session that calls, or None when no person's list narrows it: a conversation window
    of a narrowed pair, or a task born of one. read_row only."""
    context = context if context is not None else getattr(CALL, "context", None)
    if conversation_context(agent, context):
        row = read_row("SELECT person FROM conversations WHERE id=? AND agent=?", (int(context[2]), agent))
        grants = person_scope(row["person"], agent) if row else None
        return None if grants is None else {"person": row["person"], "grants": grants}
    if not context or len(context) != 3 or not re.fullmatch(r"T-[1-9][0-9]{0,17}", str(context[1])):
        return None
    try:
        return task_scope(read_row("SELECT id, owner, scope_person, source_conversation FROM tasks WHERE id=?",
                                   (parse_task(context[1]),)))
    except sqlite3.OperationalError:        # a database from before the column: no list can exist there
        return None


# A mark on the rows of a narrowed pair (person access plan, section 5; ~/dev/founderizer-plans/
# person-scope-row-mark-spec.md): conversation_messages.scope_person is the person's id on each row that the pair's
# own writers stored while the pair had a list (the person's words, the replies and lines of their locked window), and
# NULL on every other row (what a session with more wrote there, the owner's answers, the hub's lines). A filter that
# read only the row's task let through a reply with no task of its own and a message that came in a pause. The mark
# does not change, with one exception: a list back to All gives back what nobody answered (person_scope_rows).
def narrowed_mark(conv):
    """The mark of a row that the pair's own writers store now in conversation `conv` (its row, of which only the id
    is read): the person's id while the pair has a list (a row in person_scopes, whatever the conversation's mode),
    else None. The writer calls it in the transaction of its INSERT, under LOCK, where a change of the list cannot
    come between. read_row only."""
    row = read_row("SELECT c.person FROM conversations c JOIN person_scopes s ON s.person=c.person AND "
                   "s.agent=c.agent WHERE c.id=?", (conv["id"],))
    return row["person"] if row else None


def narrowed_rows_sql(alias, scope):
    """(condition, args) on conversation_messages rows `alias` for a session's read: the rows that it may read of
    what a narrowed pair wrote. scope is session_scope's, or OWNER_VIEW: the owner reads all; a session with no list
    reads no marked row; a narrowed session reads the rows with no mark and its own person's. Never NULL, so that its
    negation lets no row through. (A line of the hub's that a session with more made before the first list, and that
    nobody read then, is read at that list: person_scope_rows.)"""
    if scope == OWNER_VIEW:
        return "", ()
    if scope is None:
        return f"{alias}.scope_person IS NULL", ()
    return f"({alias}.scope_person IS NULL OR IFNULL({alias}.scope_person=?, 0))", (scope["person"],)


def narrowed_calls_sql(alias, scope):
    """(condition, args) on calls rows `alias` for a session's read (person-scope-call-mark.md): the calls that it may
    read. scope is session_scope's or task_scope's, or OWNER_VIEW: the owner reads all; a session with no list reads no
    call with a mark (calls.scope_person, call_tool); a narrowed session reads only the calls of its own person's mark,
    never a call with no mark, which a session with more made. Never NULL, so that its negation lets no row through."""
    if scope == OWNER_VIEW:
        return "", ()
    if scope is None:
        return f"{alias}.scope_person IS NULL", ()
    return f"IFNULL({alias}.scope_person=?, 0)", (scope["person"],)


NARROWED_SETTLED = "narrowed_rows_settled"      # kv: the newest message id that the one-time pass of the settle took
NARROWED_LEAD = 60          # seconds before a pair's first log line of a list from which that pass marks its rows
NARROWED_LINE = re.compile(r"P-([0-9]+)'s access with ([a-z][a-z0-9-]{1,30}): ")       # person_scope_rows' log line


def narrowed_adopted(alias, conv="?"):
    """What a list back to All gives back (person_scope_rows), as a condition on conversation_messages rows `alias`
    of the conversation `conv` (one argument, or an SQL expression): a person's message that nobody answered and that
    waits for a reader, of an open task of the conversation, or unread. Never NULL, also for a row with no task, so
    that its NOT in the settle is true where this is false (EXISTS, not IN)."""
    return (f"{alias}.who='person' AND (EXISTS (SELECT 1 FROM tasks t WHERE t.id={alias}.task AND "
            f"t.source_conversation={conv} AND t.{OPEN_TASK}) OR {alias}.read_at IS NULL) AND NOT EXISTS (SELECT 1 "
            f"FROM conversation_messages r WHERE r.reply_to={alias}.id)")


def narrowed_rows_settle():
    """Inside the caller's transaction: settle_narrowed_rows' marks. Returns how many rows it marked."""
    in_transaction("narrowed_rows_settle")
    marked = DB.execute(
        "UPDATE conversation_messages SET scope_person=(SELECT c.person FROM conversations c WHERE "
        "c.id=conversation_messages.conversation) WHERE scope_person IS NULL AND (who='person' OR reply_to IS NOT "
        "NULL) AND task IN (SELECT id FROM tasks WHERE scope_person IS NOT NULL) AND (EXISTS (SELECT 1 FROM "
        "conversations c JOIN person_scopes s ON s.person=c.person AND s.agent=c.agent WHERE "
        "c.id=conversation_messages.conversation) OR NOT ("
        f"{narrowed_adopted('conversation_messages', 'conversation_messages.conversation')}))").rowcount
    if read_row("SELECT v FROM kv WHERE k=?", (NARROWED_SETTLED,)) is None:
        top = read_row("SELECT MAX(id) n FROM conversation_messages")["n"] or 0
        pairs = {(r["person"], r["agent"]) for r in read_rows("SELECT person, agent FROM person_scopes")} | \
            {(r["person"], r["agent"]) for r in read_rows(
                "SELECT c.person, c.agent FROM tasks t JOIN conversations c ON c.id=t.source_conversation WHERE "
                "t.scope_person IS NOT NULL")}
        first = {}
        for r in read_rows("SELECT ts, what FROM log WHERE agent='owner' AND what LIKE 'P-%' ORDER BY id"):
            m = NARROWED_LINE.match(r["what"] or "")
            if m:
                first.setdefault((int(m.group(1)), m.group(2)), r["ts"])
        pairs |= set(first)
        narrowed = {(r["person"], r["agent"]) for r in read_rows("SELECT person, agent FROM person_scopes")}
        for pid, agent in sorted(pairs):
            conv = read_row("SELECT id FROM conversations WHERE person=? AND agent=?", (pid, agent))
            if conv is None:
                continue
            since = first[(pid, agent)] - NARROWED_LEAD if (pid, agent) in first else None
            marked += DB.execute(
                "UPDATE conversation_messages SET scope_person=? WHERE conversation=? AND id<=? AND scope_person IS "
                "NULL AND (who='person' OR reply_to IS NOT NULL)" + ("" if since is None else " AND created>=?") +
                ("" if (pid, agent) in narrowed else f" AND NOT ({narrowed_adopted('conversation_messages')})"),
                (pid, conv["id"], top, *([] if since is None else [since]),
                 *([] if (pid, agent) in narrowed else [conv["id"]]))).rowcount
        DB.execute("INSERT INTO kv(k,v) VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",
                   (NARROWED_SETTLED, str(top)))
    marked += DB.execute(
        "UPDATE conversation_messages SET scope_person=(SELECT r.scope_person FROM conversation_messages r WHERE "
        "r.id=conversation_messages.reply_to) WHERE scope_person IS NULL AND reply_to IN (SELECT id FROM "
        "conversation_messages WHERE scope_person IS NOT NULL)").rowcount
    return marked


NARROWED_TASKS_SETTLED = "narrowed_tasks_settled"      # kv: narrowed_tasks_settle ran (one time)


def narrowed_tasks_settle():
    """Inside the caller's transaction, one time (kv NARROWED_TASKS_SETTLED, written in the same transaction): the
    conversation tasks that the pair's marked reply ended but that have no person. From 11 to 20 November 2026 a first
    list left the open conversation task with none (c8373b797 gives it one), and such a task's result, the locked
    reply, then reached each session of the agent. Each gets the person of its reply's mark, and the readers that keep
    a narrowed pair's task apart (narrowed_from, history_scope_sql) hide it; its result stays, for the owner reads all.
    The messages come first (CROSS JOIN): conversation_messages.task has no index. After conversation_task_end gives
    every such task its person, a later run would only find a task of a time at All that rule 2 marked. Returns how
    many tasks it changed."""
    in_transaction("narrowed_tasks_settle")
    if read_row("SELECT v FROM kv WHERE k=?", (NARROWED_TASKS_SETTLED,)) is not None:
        return 0
    rows = DB.execute(
        "SELECT DISTINCT t.id, m.scope_person FROM conversation_messages m CROSS JOIN tasks t ON t.id=m.task AND "
        "t.source_conversation=m.conversation WHERE m.scope_person IS NOT NULL AND m.who='agent' AND m.reply_to IS NOT "
        "NULL AND t.source_message IS NOT NULL AND t.state='completed' AND t.scope_person IS NULL").fetchall()
    for r in rows:
        DB.execute("UPDATE tasks SET scope_person=? WHERE id=? AND scope_person IS NULL", (r["scope_person"], r["id"]))
    DB.execute("INSERT INTO kv(k,v) VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",
               (NARROWED_TASKS_SETTLED, str(len(rows))))
    return len(rows)


NARROWED_ENDED_SETTLED = "narrowed_ended_settled"      # kv: narrowed_ended_settle ran (one time)
# the owner's log line of a rename (rename_agent), with the agent's name of before and its new one: the log keeps the
# name of its time, so narrowed_spans carries a pair's lines of before a rename over to the new name
RENAMED_LINE = re.compile(r"renamed (?:agent|the manager) ([a-z][a-z0-9-]{1,30}) to ([a-z][a-z0-9-]{1,30})[ ,]")


def narrowed_spans():
    """{(person id, agent): [(from, until or None), ...]}: the times in which each pair had a list, oldest first, from
    the owner's log lines of a change of a list (person_scope_rows' NARROWED_LINE), under the agent's name of now
    (RENAMED_LINE), and an open span for each pair that has a list now (person_scopes). A line "all of it" ends the
    open span; each other line opens one, or keeps it open. read_rows only: safe inside a caller's transaction."""
    spans = {}
    for r in read_rows("SELECT ts, what FROM log WHERE agent='owner' AND (what LIKE 'P-%' OR what LIKE 'renamed %') "
                       "ORDER BY id"):
        what = r["what"] or ""
        moved = RENAMED_LINE.match(what)
        if moved:
            for pid, agent in [k for k in spans if k[1] == moved.group(1)]:
                spans.setdefault((pid, moved.group(2)), []).extend(spans.pop((pid, agent)))
            continue
        m = NARROWED_LINE.match(what)
        if not m:
            continue
        mine = spans.setdefault((int(m.group(1)), m.group(2)), [])
        is_open = bool(mine) and mine[-1][1] is None
        if what[m.end():].startswith("all of it"):
            if is_open:
                mine[-1] = (mine[-1][0], r["ts"])
        elif not is_open:
            mine.append((r["ts"], None))
    for r in read_rows("SELECT person, agent, updated FROM person_scopes"):
        mine = spans.setdefault((r["person"], r["agent"]), [])
        if not mine or mine[-1][1] is not None:
            mine.append((r["updated"], None))
    return spans


def narrowed_ended_settle():
    """Inside the caller's transaction, one time (kv NARROWED_ENDED_SETTLED, written in the same transaction): the
    conversation tasks with no person to which today's code gives one. A conversation task has its person when it ended
    while its pair had a list (by its delivered time, else its last activity), or when it is open and its pair has a
    list now. From 11 to 20 November 2026 a task that a locked window worked in but that ended another way (canceled,
    failed), or that is still open, kept none, so its call records stayed readable to each session with more
    (history_scope_sql reads the task's person, so the history needs no change). A task that ended at All gets nothing,
    and so does an open task of a pair at All: with a person and no list it would lose the agent's tools (task_scope).
    It reads the log once (narrowed_spans), each pair's tasks by task_of_conversation, and no call record. Two limits
    of the log: a lost "all of it" line leaves a span open, so a task that ended after it gets the person (it fails
    closed); and a task that ended in a span after it was open at All loses its records of the time at All too, as each
    task that was open at a first list does since 20 November 2026. Returns how many tasks it changed."""
    in_transaction("narrowed_ended_settle")
    if read_row("SELECT v FROM kv WHERE k=?", (NARROWED_ENDED_SETTLED,)) is not None:
        return 0
    changed = 0
    for (pid, agent), mine in sorted(narrowed_spans().items()):
        conv = read_row("SELECT id FROM conversations WHERE person=? AND agent=?", (pid, agent))
        if conv is None:
            continue
        listed = person_scope(pid, agent) is not None
        for t in read_rows(f"SELECT id, delivered, last_activity, ({OPEN_TASK}) AS open FROM tasks WHERE "
                           f"source_conversation=? AND source_message IS NOT NULL AND scope_person IS NULL",
                           (conv["id"],)):
            at = None if t["open"] else t["delivered"] or t["last_activity"]
            if (t["open"] and listed) or \
                    (at is not None and any(a <= at and (b is None or at < b) for a, b in mine)):
                changed += DB.execute("UPDATE tasks SET scope_person=? WHERE id=? AND scope_person IS NULL",
                                      (pid, t["id"])).rowcount
    DB.execute("INSERT INTO kv(k,v) VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",
               (NARROWED_ENDED_SETTLED, str(changed)))
    return changed


NARROWED_CALLS_SETTLED = "narrowed_calls_settled"      # kv: narrowed_calls_settle ran (one time)


def narrowed_calls_settle():
    """Inside the caller's transaction, one time (kv NARROWED_CALLS_SETTLED, written in the same transaction): the mark
    (calls.scope_person) of the calls that a narrowed pair's sessions made before the column came. For each time in
    which a pair had a list (narrowed_spans), each call of its conversation window (calls.conversation) and each call
    of its conversation tasks gets the person. The second needs no window: calls.conversation came on 18 November
    2026 (ed18fb230), and the lists on 11 November. It reads the log once, and of calls only each pair's rows, by the
    indexes call_conversation and call_task_ok. Returns how many calls it marked."""
    in_transaction("narrowed_calls_settle")
    if read_row("SELECT v FROM kv WHERE k=?", (NARROWED_CALLS_SETTLED,)) is not None:
        return 0
    marked = 0
    for (pid, agent), mine in sorted(narrowed_spans().items()):
        conv = read_row("SELECT id FROM conversations WHERE person=? AND agent=?", (pid, agent))
        if conv is None:
            continue
        for a, b in mine:
            until, more = ("", ()) if b is None else (" AND ts<?", (b,))
            marked += DB.execute("UPDATE calls SET scope_person=? WHERE conversation=? AND scope_person IS NULL AND "
                                 "ts>=?" + until, (pid, conv["id"], a, *more)).rowcount
            marked += DB.execute("UPDATE calls SET scope_person=? WHERE task IN (SELECT id FROM tasks WHERE "
                                 "source_conversation=? AND source_message IS NOT NULL) AND scope_person IS NULL AND "
                                 "ts>=?" + until, (pid, conv["id"], a, *more)).rowcount
    DB.execute("INSERT INTO kv(k,v) VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v",
               (NARROWED_CALLS_SETTLED, str(marked)))
    return marked


def settle_narrowed_rows():
    """At the start, after the schema: the marks (narrowed_mark) of a narrowed pair's rows that were stored before
    the column came, or by a hub of the release before it during a restart or after a rollback, which stores NULL
    (person-scope-row-mark-spec.md, section C). It only adds marks.

    1. Each start: a message of the person, or a reply, whose task has scope_person (a line of the hub's that
       joined the task keeps none: a list back to All gives back only the person's messages), but for a pair at All
       now not what a widening gave back (narrowed_adopted), whose ended task keeps its person.
    2. Each start: a reply to a marked row.
    3. One time, up to the newest id of that moment (kv NARROWED_SETTLED): in each conversation whose pair had a list
       at any time (a row of person_scopes, a task with scope_person, or the owner's log line of person_scope_rows),
       each message of the person and each reply, from NARROWED_LEAD seconds before the pair's first such line, or
       from the conversation's start when the log has none. For a pair at All now it leaves out what a widening
       gives back (narrowed_adopted).
    4. One time (kv NARROWED_TASKS_SETTLED), after the marks: a completed conversation task that a marked reply
       ended, with no person, gets the reply's person (narrowed_tasks_settle).
    5. One time (kv NARROWED_ENDED_SETTLED), after the marks: an old conversation task with no person that ended while
       its pair had a list, or that is open while its pair has one now, gets the person (narrowed_ended_settle).
    6. One time (kv NARROWED_CALLS_SETTLED), after narrowed_ended_settle: each call of a pair's conversation window,
       and each call of its conversation tasks, made while the pair had a list, gets the person (narrowed_calls_settle).
       Its limits: a call with no task from before 18 November 2026 keeps no mark, for nothing in its row names its
       conversation; a hub of the release before, during a restart or after a rollback, writes calls with no mark,
       and this pass does not run again for them; and of the old rows, a wide window's call that ended after a first
       list gets the mark (a row keeps the time of its end only), so the locked window reads it, as it did before the
       mark came.

    The hub kept no list of before, no time back at All and no writer of a reply, so rule 3 fails closed: the pair's
    words of a time at All after its first list stay hidden from the sessions with more, which is a loss, where a
    leak would be the worse fault. An old writer's row with no task and no reply_to stays open (a known hole). An error
    is logged, and the start goes on."""
    try:
        with transaction():
            marked = narrowed_rows_settle()
            if marked:
                log_row("hub", f"marked {marked} row(s) of conversations of narrowed pairs (person access plan, "
                               f"section 5)")
            tasks = narrowed_tasks_settle()             # after the marks: a reply that rule 2 marks counts
            if tasks:
                log_row("hub", f"gave {tasks} ended conversation task(s) of narrowed pairs their person")
            ended = narrowed_ended_settle()             # after the marks and narrowed_tasks_settle
            if ended:
                log_row("hub", f"gave {ended} old conversation task(s) of narrowed pairs their person")
            calls = narrowed_calls_settle()             # after narrowed_ended_settle
            if calls:
                log_row("hub", f"marked {calls} call record(s) of narrowed pairs with their person")
    except Exception as e:
        print_fault()
        log("hub", f"the rows of narrowed pairs could not be marked at this start: {type(e).__name__}: {e}")


def scope_effective(agent, grants):
    """What a list leaves of the agent's own access: {"repos": {owner/name: level}, "secrets": {bws ref: level}}, each
    at the lower of the list's level and the agent's. A kind that a list cannot name gives nothing: no MCP server and no
    Google service reach a narrowed session. An entry that the agent does not hold now gives nothing, and works again
    once the agent holds it."""
    a = agents().get(agent) or {}
    held = {"repo": a.get("repos") or {}, "secret": a.get("secrets") or {}}
    out = {"repo": {}, "secret": {}}
    for rid, level in (grants or {}).items():
        kind, what = resource_parts(rid)
        order = RESOURCE_LEVELS.get(kind) if kind in SCOPE_KINDS else None
        mine = held[kind].get(what) if order else None
        if order and level in order and mine in order:
            out[kind][what] = order[min(order.index(level), order.index(mine))]
    return {"repos": out["repo"], "secrets": out["secret"]}


def scope_refusal(agent):
    """Why a narrowed conversation of this agent waits now, in the owner's words, or None (plan, section 6). A narrowed
    window runs locked, as a closed conversation does, so it needs that runtime to be the agent's own (one account,
    whoever the agent talks to) and a helper that knows the narrowed start. The person never reads these:
    conversation_refusal gives them its generic sentence. read_row only: safe inside chat_route's transaction."""
    a, display = agents().get(agent) or {}, agent_display(agent)
    # (a pair whose agent has its Shell box off, or whose fleet has contacts.v2 off, is closed for everybody, not
    # narrowed: conversation_mode never says "narrowed" for it, and person_agent_view gives it no wait reason)
    runtime = a.get("runtime")
    if not runtime_fact(runtime, "conversation") or runtime != setting("conversations.closed_runtime"):
        return (f"{display} runs on {runtime_fact(runtime, 'label', runtime)}, which cannot run a locked conversation "
                f"on its own account yet.")
    st = read_row("SELECT data FROM machine_status WHERE agent=?", (agent,))
    try:
        features = (json.loads(st["data"]).get("features") or []) if st else []
    except (TypeError, ValueError, AttributeError):
        features = []
    if NARROWED_THREADS not in features:
        return f"{display}'s helper is older than narrowed conversations; they start after its next update."
    return None


def scope_ready(pid, agent):
    """True when a narrowed pair's conversation may start now (scope_refusal has nothing to say)."""
    return scope_refusal(agent) is None


def person_scope_body(value):
    """The checked `scopes` of one POST /ui/people: {agent: None for All, or {resource id: level}}. It refuses only what
    is never valid (plan, section 6): an agent that is not there, a kind other than repo: and secret:, a resource that
    the agent does not hold now, a level above the agent's, and deploy, which no list reaches. ValueError in the
    owner's words."""
    if not isinstance(value, dict) or not 1 <= len(value) <= PERSON_AGENTS_MAX:
        raise ValueError(f"scopes is {{agent: null or {{resource: level}}}} for 1 to {PERSON_AGENTS_MAX} agents")
    out = {}
    for agent, grants in value.items():
        a = agents().get(agent) if isinstance(agent, str) else None
        if not a or a.get("role") not in ("worker", "lead"):
            raise ValueError(f"{agent} is no worker or lead of this fleet")
        if grants is None:
            out[agent] = None
            continue
        if not isinstance(grants, dict) or len(grants) > REPOS_MOST + 200:
            raise ValueError("a list is {resource: level}")
        held, clean = {"repo": a.get("repos") or {}, "secret": a.get("secrets") or {}}, {}
        for rid, level in grants.items():
            kind, what = resource_parts(rid)
            if kind not in SCOPE_KINDS:
                raise ValueError(f"{rid}: a list holds repositories (repo:) and secrets (secret:) only")
            order, mine = RESOURCE_LEVELS[kind], held[kind].get(what)
            if mine not in order:
                raise ValueError(f"{rid}: {agent_display(agent)} does not hold it")
            if level not in order or level == "deploy" or order.index(level) > order.index(mine):
                raise ValueError(f"{rid}: its level is at most {mine}, and never deploy")
            clean[rid] = level
        out[agent] = clean
    return out


def person_agents_rows(p, agents, t0):
    """Inside the owner's write of a person (ui_person, and a role's set of Founderizer for Teams, design 3): the
    agents that the person can talk to become `agents`, checked names (person_agent_names), each added at t0, and the
    standing items that the person gave an agent that they lost end (AUTONOMY.md P3). A list of an agent that the
    person lost stays in person_scopes, as after an untick by hand."""
    in_transaction("person_agents_rows")
    DB.execute("DELETE FROM person_agents WHERE person=?", (p["id"],))
    for agent in agents:
        DB.execute("INSERT INTO person_agents(person,agent,added) VALUES(?,?,?)", (p["id"], agent, t0))
    standing_person_rows(p["id"], f"{p['name']} no longer writes to that agent", t0, agents)


def person_scope_done(p, ended, dropped, said):
    """After the commit of a write of a person's lists, with what person_scope_rows returned, as person_remove ends a
    removed person's work: the open work that a newly narrowed conversation opened before its list ends, the tokens
    that the hub kept for the changed conversations go, and the owner's log lines of each change are written (each
    one a NARROWED_LINE, which narrowed_spans reads). Empty lists do nothing."""
    removed_conversation_tasks_end(ended, f"{p['name']}'s access with this agent was narrowed")
    thread_tokens_drop(dropped)
    for line in said:
        log("owner", line)


def person_scope_rows(p, scopes, t0):
    """Inside ui_person's transaction: the person's lists as the owner wrote them, and what a change of each one does
    (plan, section 7). The pair's conversation sessions end (conversation_sessions_end, with their waits), so the next
    message starts the window the new way. A list back to All gives the open conversation task its person no more, so
    it works with the agent's own tools again: the owner widened it; and the person's messages that nobody answered
    lose their mark, so that the next window reads them (narrowed_adopted). A first list collects the open work that the
    conversation opened earlier, which ui_person ends right after the commit, and gives the open conversation task its
    person, so that its result (the locked window's reply) and its records stay the narrowed pair's (section 5); it
    reads the hub's lines that nobody read and the open conversation task's filed lines, and ends with the open work
    an open conversation task that holds no message of the person. A list back to All takes a given-back message out
    of a task that ended.
    Returns (those task rows, the ids of the conversations whose kept tokens go, the log lines that ui_person writes
    after the commit)."""
    in_transaction("person_scope_rows")
    ended, dropped, said = [], [], []
    for agent, grants in scopes.items():
        if not person_may(p["id"], agent):
            raise Refusal(400, f"{agent_display(agent)} is not on {p['name']}'s list")
        before = person_scope(p["id"], agent)
        if before == grants:
            continue        # an unchanged list keeps its row and its time, so the mode and the window stay as they are
        if grants is None:
            DB.execute("DELETE FROM person_scopes WHERE person=? AND agent=?", (p["id"], agent))
        else:
            DB.execute("INSERT INTO person_scopes(person,agent,grants,updated) VALUES(?,?,?,?) ON CONFLICT(person,agent) "
                       "DO UPDATE SET grants=excluded.grants, updated=excluded.updated",
                       (p["id"], agent, json.dumps(grants, sort_keys=True), t0))
        conversation_sessions_end(t0, f"{p['name']}'s access with {agent_display(agent)} changed", person=p["id"],
                                  agent=agent)
        convs = [r["id"] for r in read_rows("SELECT id FROM conversations WHERE person=? AND agent=?",
                                            (p["id"], agent))]
        marks = ",".join("?" * len(convs))
        if convs and grants is None:
            # what nobody answered goes back with the pair, as its open task does (narrowed_adopted): a message that
            # waits must have a reader. Each reply, and each message that a reply answered, keeps its mark (section 5)
            # A given-back message leaves a task that ended (a canceled conversation task keeps its person, so its
            # records stay hidden): the task conditions of the reads would hide it and its reply again, and the next
            # start would mark them again. The history row keeps a copy of the task, so it is indexed again.
            for cid in convs:
                given = f"conversation=? AND scope_person=? AND {narrowed_adopted('conversation_messages')}"
                left = [r["id"] for r in read_rows(
                    f"SELECT id FROM conversation_messages WHERE {given} AND task IS NOT NULL AND NOT EXISTS (SELECT 1 "
                    f"FROM tasks t WHERE t.id=conversation_messages.task AND t.{OPEN_TASK})", (cid, p["id"], cid))]
                DB.execute(f"UPDATE conversation_messages SET scope_person=NULL, task=(SELECT t.id FROM tasks t WHERE "
                           f"t.id=conversation_messages.task AND t.{OPEN_TASK}) WHERE {given}", (cid, p["id"], cid))
                for cm in left:
                    history_rewrite("conversation", cm, cm_ref(cm))
            DB.execute(f"UPDATE tasks SET scope_person=NULL WHERE source_conversation IN ({marks}) AND {OPEN_TASK}",
                       tuple(convs))
        if convs and before is None:
            ended += read_rows(f"SELECT * FROM tasks WHERE source_conversation IN ({marks}) AND source_message IS NULL "
                               f"AND {OPEN_TASK}", tuple(convs))
            # a line of the hub's that nobody read yet (a result of work of the time at All) is a session's with more:
            # it is read now, so it never reaches the locked window, and no reply of that window gives it a new
            # conversation task (conversation_task_end); so are the lines that the fleet filed under the open
            # conversation task (its `say` events: a result, an agent's answer), which the window reads with the
            # person's messages. An open conversation task that holds no message of the person (a line opened it)
            # ends with the open work, as nothing would end it before a widening
            lines = f"conversation IN ({marks}) AND read_at IS NULL AND who='action' AND event IS NOT NULL"
            DB.execute(f"UPDATE events SET read_at=COALESCE(read_at,?) WHERE id IN (SELECT event FROM "
                       f"conversation_messages WHERE {lines})", (t0, *convs))
            DB.execute(f"UPDATE conversation_messages SET read_at=? WHERE {lines}", (t0, *convs))
            # (not the owner's steer of that task, which is his guidance: the locked window reads it, and his app
            # shows it read only once a session read it). An agent's message that this reads for nobody is told to
            # its sender in one line, as end_waits tells it when a task ends first, with no word of the message
            filed = (f"kind='say' AND read_at IS NULL AND task IN (SELECT id FROM tasks WHERE source_conversation IN "
                     f"({marks}) AND source_message IS NOT NULL AND {OPEN_TASK}) AND id NOT IN (SELECT event_id FROM "
                     f"steers WHERE event_id IS NOT NULL)")
            unread = read_rows(f"SELECT m.*, (SELECT task FROM events WHERE id=m.event_id) AS e_task FROM "
                               f"agent_messages m WHERE m.event_id IN (SELECT id FROM events WHERE {filed})",
                               tuple(convs))
            DB.execute(f"UPDATE events SET read_at=? WHERE {filed}", (t0, *convs))
            for m in unread:
                open_ = read_row(f"SELECT 1 FROM tasks WHERE id=? AND {OPEN_TASK}", (m["sender_task"],)) \
                    if m["sender_task"] else None
                if m["waits"] == 1 and m["wait_end"] is None:
                    DB.execute("UPDATE agent_messages SET wait_end=? WHERE id=?",
                               (f"{tref(m['e_task'])} will not read it", m["id"]))
                    log_row("hub", f"the wait of AM-{m['id']} ended: {tref(m['e_task'])} will not read it")
                    line = (f"[hub] AM-{m['id']} will get no answer: {tref(m['e_task'])} will not read it. Go on "
                            f"without it, or {wait_next(m['sender'])}.") if open_ else None
                else:
                    line = f"[hub] AM-{m['id']} reached {tref(m['e_task'])}, which will not read it." \
                        if m["waits"] is None and (open_ or role_of(m["sender"]) == "manager") else None
                if line:
                    task = m["sender_task"] if open_ else None
                    event_rows([(m["sender"], "say", filed_about(m["sender"], "say", task), line, None)], t0)
            ended += read_rows(f"SELECT * FROM tasks WHERE source_conversation IN ({marks}) AND source_message IS NOT "
                               f"NULL AND {OPEN_TASK} AND NOT EXISTS (SELECT 1 FROM conversation_messages m WHERE "
                               f"m.task=tasks.id AND m.who='person')", tuple(convs))
            DB.execute(f"UPDATE tasks SET scope_person=? WHERE source_conversation IN ({marks}) AND source_message IS "
                       f"NOT NULL AND scope_person IS NULL AND {OPEN_TASK}", (p["id"], *convs))
        dropped += convs
        said.append(f"P-{p['id']}'s access with {agent}: " + ("all of it" if grants is None else
                                                              f"{len(grants)} resource(s) of its own"))
    return ended, dropped, said


def scope_view(agent, grants):
    """One person's list on one agent for the owner's app: each entry with its name in words, its level, and whether
    the agent holds it now (a lost grant stays in the list and works again when the agent gets it back)."""
    a = agents().get(agent) or {}
    held = {"repo": a.get("repos") or {}, "secret": a.get("secrets") or {}}
    out = []
    for rid, level in sorted((grants or {}).items()):
        kind, what = resource_parts(rid)
        if kind not in SCOPE_KINDS:
            continue
        title = what if kind == "repo" else ((logins().get(what) or {}).get("title") or what)
        out.append({"resource": rid, "title": title, "level": level, "held": what in held[kind]})
    return out


# The tokens that the door for threads keeps (plan, section 3): {(conversation id, repository, level): (token, ends)},
# in the hub's memory only. A run of calls of one thread makes one token, which never leaves this process; an entry
# goes when its conversation's credential is revoked, when the list changes, or when its hour ends, and a restart
# forgets them all.
THREAD_TOKENS = {}
THREAD_TOKENS_LOCK = threading.Lock()


def thread_tokens_drop(cids):
    """Forget the kept tokens of these conversations (a list changed, or their credential was revoked)."""
    wanted = set(cids)
    with THREAD_TOKENS_LOCK:
        for key in [k for k in THREAD_TOKENS if k[0] in wanted]:
            del THREAD_TOKENS[key]


THREAD_ANSWER_MAX = 2 * 1024 * 1024     # bytes of one GitHub answer that a repository call reads, at most
THREAD_COMMITS_DAY = 50                 # commits of one narrowed conversation in one day (plan, section 3)


def thread_call(agent, a, need):
    """(conversation id, repository, level, the request function) of one repository call of a narrowed thread (plan,
    section 3), or ToolError. It fails closed: a session without a list has no repository call. The repository must
    be one of the list's, at the lower of the list's and the agent's levels and never above write; the token is the
    kept one of this conversation, repository and level, made through the door when the fleet has one. Outside the
    hub's lock: the door's token route refuses the lock, and GitHub can take seconds."""
    scope, context = session_scope(agent), getattr(CALL, "context", None)
    if scope is None:
        raise ToolError("Repository calls work only in a conversation whose person has a list of their own.")
    t = read_row("SELECT source_conversation FROM tasks WHERE id=?", (parse_task(context[1]),)) \
        if context and len(context) == 3 and re.fullmatch(r"T-[1-9][0-9]{0,17}", str(context[1])) else None
    cid = t["source_conversation"] if t else None
    if cid is None:
        raise ToolError("No message of this conversation waits for an answer now, so no task is open here. Call "
                        "read_messages.")
    repo = str(a.get("repo") or "")
    level = scope_effective(agent, scope["grants"])["repos"].get(repo)
    if level is None:
        raise ToolError(f"{clip(repo, 100) or 'That repository'} is {SCOPE_OUTSIDE}. {SCOPE_STOP}")
    level = "write" if level == "deploy" else level
    if need == "write" and level != "write":
        raise ToolError(f"This conversation may only read {clip(repo, 100)}. A change there is {SCOPE_OUTSIDE}. "
                        f"{SCOPE_STOP}")
    return cid, repo, level, thread_request(thread_token(agent, cid, repo, level))


def thread_recheck(agent, cid, repo):
    """The check right before a repository write (plan, section 3): the person's list still gives this repository at
    write, the conversation is still open and the person is not blocked, so an owner's change that lands while the
    call runs writes nothing."""
    import thread_door

    def recheck():
        scope = session_scope(agent)
        conv = read_row("SELECT c.state, p.blocked FROM conversations c JOIN people p ON p.id=c.person WHERE c.id=?",
                        (cid,))
        if scope is None or not conv or conv["state"] != "open" or conv["blocked"] is not None or \
                scope_effective(agent, scope["grants"])["repos"].get(repo) not in ("write", "deploy"):
            raise thread_door.Refused(f"{clip(repo, 100)} is {SCOPE_OUTSIDE} now. Nothing was written. {SCOPE_STOP}")
    return recheck


def thread_token(agent, cid, repo, level):
    """The kept token of one conversation, repository and level, or a new one for at most its hour. Never returned
    to a session, never logged and never stored."""
    key, t0 = (cid, repo, level), time.time()
    with THREAD_TOKENS_LOCK:
        kept = THREAD_TOKENS.get(key)
        if kept and kept[1] > t0 + 60:
            return kept[0]
    try:
        tokens, _errors = github_tokens({repo: level}, agent)
    except GitHubError:
        tokens = []
    got = next((x for x in tokens if repo in (x.get("repos") or [])), None)
    if not got:
        raise ToolError("GitHub gave no access to this repository now. Try again later, or tell them to ask the owner.")
    ends = t0 + 55 * 60
    try:            # never past the token's own end, which a door may give closer than an hour
        ends = min(ends, datetime.datetime.fromisoformat(str(got.get("expires_at")).replace("Z", "+00:00"))
                   .timestamp() - 60)
    except (TypeError, ValueError):
        pass
    with THREAD_TOKENS_LOCK:
        for old in [k for k, v in THREAD_TOKENS.items() if v[1] <= t0]:
            del THREAD_TOKENS[old]          # the ones whose time is over go as a new one comes
        THREAD_TOKENS[key] = (got["token"], ends)
    return got["token"]


def thread_request(token):
    """The request function of thread_door's calls, bound to one token: the hub's GitHub address (CFG github_api, or
    a stand-in in tests), no redirect to another host, and a cap on each answer. It never raises for an HTTP status."""
    import thread_door

    def req(method, path, body=None, accept=None):
        headers = {"Accept": accept or "application/vnd.github+json", "Authorization": "Bearer " + token,
                   "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "founderizer-hub"}
        if body is not None:
            headers["Content-Type"] = "application/json"
        request = urllib.request.Request((CFG.get("github_api") or GITHUB_API) + path, method=method, headers=headers,
                                         data=None if body is None else json.dumps(body).encode())
        try:
            with GITHUB_OPENER.open(request, timeout=20) as r:
                status, raw = r.status, r.read(THREAD_ANSWER_MAX + 1)
        except urllib.error.HTTPError as e:
            status, raw = e.code, e.read(THREAD_ANSWER_MAX + 1)
        except (urllib.error.URLError, OSError, ValueError, http.client.HTTPException):
            raise thread_door.Refused("GitHub did not answer.") from None
        if status == 401:           # GitHub no longer takes this token: the next call makes a new one
            with THREAD_TOKENS_LOCK:
                for key in [k for k, v in THREAD_TOKENS.items() if v[0] == token]:
                    del THREAD_TOKENS[key]
        if len(raw) > THREAD_ANSWER_MAX:
            raise thread_door.Refused("GitHub's answer is too large for one call.")
        try:
            return status, json.loads(raw) if raw else None
        except ValueError:
            return status, None
    return req


def thread_run(fn, *args):
    """One call of thread_door, its refusal a ToolError in the module's own fixed words, masked: never GitHub's text."""
    import thread_door
    try:
        return mask_secrets(fn(*args))
    except thread_door.Refused as e:
        raise ToolError(mask_secrets(str(e))) from None


def t_repo_files(agent, a):
    import thread_door
    _cid, repo, _level, req = thread_call(agent, a, "read")
    return thread_run(thread_door.repo_files, req, repo, str(a.get("path") or ""), a.get("ref"))


